import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.CRFziyHp.js";const c=JSON.parse('{"title":"圈子与笔记","description":"灵萌圈子与笔记功能配置：笔记审核、圈子分类、入圈规则与区域化内容运营设置说明。","frontmatter":{"title":"圈子与笔记","description":"灵萌圈子与笔记功能配置：笔记审核、圈子分类、入圈规则与区域化内容运营设置说明。"},"headers":[],"relativePath":"features/circle-note.md","filePath":"features/circle-note.md","lastUpdated":1785013113000}'),l={name:"features/circle-note.md"};function i(n,t,s,d,h,g){return r(),e("div",null,[...t[0]||(t[0]=[o('<h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>管理用户发布的笔记内容、圈子分类与入圈审核，并按区域控制笔记发布规则。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>已创建至少一个 <strong>区域</strong>（<strong>区域管理 → 区域列表</strong>）。</li><li>管理员账号具备内容、圈子相关菜单权限。</li><li>文件存储已配置（否则无法上传笔记图片），见 <a href="/features/storage">文件存储</a>。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><h3 id="笔记区域规则" tabindex="-1">笔记区域规则 <a class="header-anchor" href="#笔记区域规则" aria-label="Permalink to &quot;笔记区域规则&quot;">​</a></h3><p>路径：<strong>区域管理 → 笔记配置</strong></p><p>按区域（或平台默认）设置：</p><ul><li>是否允许发布笔记、图片、视频</li><li>审核模式（先发后审 / 先审后发等，以页面为准）</li><li>单篇字数、图片数量等限制</li></ul><h3 id="笔记热度与标签" tabindex="-1">笔记热度与标签 <a class="header-anchor" href="#笔记热度与标签" aria-label="Permalink to &quot;笔记热度与标签&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>区域管理 → 笔记热度</strong></td><td>热榜算法、权重参数</td></tr><tr><td><strong>区域管理 → 热帖精帖配置</strong></td><td>精华帖、热门标识规则</td></tr><tr><td><strong>社交圈子 → 热度日志</strong></td><td>查看热度变更记录</td></tr></tbody></table><h3 id="圈子管理" tabindex="-1">圈子管理 <a class="header-anchor" href="#圈子管理" aria-label="Permalink to &quot;圈子管理&quot;">​</a></h3><p>路径：<strong>社交圈子 → 圈子管理</strong></p><ul><li>创建 / 编辑圈子：名称、封面、所属区域、是否公开</li><li>设置圈子负责人、分类</li></ul><p>相关入口：</p><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>社交圈子 → 圈子分类</strong></td><td>维护圈子类目</td></tr><tr><td><strong>社交圈子 → 入圈申请</strong></td><td>审核用户加入申请</td></tr><tr><td><strong>社交圈子 → 笔记管理</strong></td><td>查看、下架、置顶用户笔记</td></tr></tbody></table><h3 id="话题-可选" tabindex="-1">话题（可选） <a class="header-anchor" href="#话题-可选" aria-label="Permalink to &quot;话题（可选）&quot;">​</a></h3><p><strong>社交圈子 → 话题管理</strong>、<strong>话题 PK</strong>、<strong>话题活动</strong> 用于运营话题类活动，与圈子配合使用。</p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>笔记与圈子均绑定 <strong>region_id</strong>：</p><ol><li><strong>区域管理 → 区域列表</strong>：确认目标区域已启用。</li><li><strong>区域管理 → 笔记配置</strong>：该区域发布规则。</li><li>创建圈子时选择所属区域；用户只能看到本区域或有权限的圈子内容。</li></ol><p>平台默认配置（region_id=0）作为未单独配置区域的兜底。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>在 <strong>笔记配置</strong> 中开启某区域「允许发笔记」。</li><li>客户端切换至该区域，成功发布一篇带图笔记。</li><li><strong>社交圈子 → 笔记管理</strong> 中可见该笔记；若为先审后发，审核通过后用户端才展示。</li><li>创建测试圈子，客户端能搜索并申请加入；<strong>入圈申请</strong> 中可处理申请。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>用户发不了笔记</strong></p><ul><li>检查 <strong>笔记配置</strong> 是否关闭图片/视频或整站禁止发布。</li><li>确认 <strong>文件存储</strong> 正常。</li><li>用户是否被禁言（<strong>用户管理</strong> 中查看）。</li></ul><p><strong>看不到圈子入口</strong></p><ul><li>圈子是否绑定正确区域；用户当前区域与圈子区域不一致时可能不可见。</li><li>UI 侧栏是否配置圈子 Tab，见 <a href="/features/ui">页面与 TabBar</a>。</li></ul><p><strong>笔记审核积压</strong></p><ul><li><strong>社交圈子 → 笔记管理</strong> 批量处理；调整 <strong>笔记配置</strong> 审核策略。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/config/region">区域管理</a></li><li><a href="/features/vote-selection">投票与评选</a></li><li><a href="/features/ui">页面与 TabBar</a></li></ul>',33)])])}const b=a(l,[["render",i]]);export{c as __pageData,b as default};
